1	// Package mevwatch implements mempool risk detection.
2	package mevwatch
3	
4	import (
5		"sort"
6		"strconv"
7	)
8	
9	// Swap is one observed swap in a pending or confirmed transaction.
10	type Swap struct {
11		TxHash   string
12		Pool     string
13		Trader   string
14		In       int64
15		Out      int64
16		GasPrice int64
17		Index    int
18	}
19	
20	// Finding is one risk conclusion with the evidence that produced it.
21	type Finding struct {
22		TxHash   string
23		Kind     string
24		Severity int
25		Evidence []string
26	}
27	
28	// Detect flags sandwich and displacement patterns around one victim swap.
29	// It applies the built-in block rules to one transaction, so its conclusion
30	// matches DetectBlock for the same records: neighbours are the adjacent
31	// swaps inside the victim's own pool ordered by Index, never swaps from
32	// other pools and never positions in the input slice. Reordering the input
33	// or interleaving other pools therefore cannot change the result. The
34	// victim's pool's last swap is still checked for displacement against its
35	// predecessor; a victim that is absent or first in its pool has no
36	// conclusion. The passed slice is never modified.
37	func Detect(swaps []Swap, victim string) []Finding {
38		rules := BuiltinVersion().Rules
39		target, ok := findSwap(swaps, victim)
40		if !ok {
41			return nil
42		}
43		// Collect the victim's pool into a private slice before sorting, so the
44		// caller's records and their order stay untouched.
45		pool := make([]Swap, 0, len(swaps))
46		for _, s := range swaps {
47			if s.Pool == target.Pool {
48				pool = append(pool, s)
49			}
50		}
51		sort.Slice(pool, func(i, j int) bool { return pool[i].Index < pool[j].Index })
52		pos := -1
53		for i, s := range pool {
54			if s.TxHash == victim {
55				pos = i
56				break
57			}
58		}
59		if pos <= 0 {
60			// No preceding swap in the victim's pool: no neighbour can be
61			// evidence, regardless of other pools' gas prices.
62			return nil
63		}
64		front := pool[pos-1]
65		var back *Swap
66		if pos+1 < len(pool) {
67			back = &pool[pos+1]
68		}
69		if back != nil &&
70			front.Trader == back.Trader && front.Trader != target.Trader &&
71			front.GasPrice > target.GasPrice && back.GasPrice > target.GasPrice {
72			return []Finding{{
73				TxHash: victim, Kind: "sandwich", Severity: rules.Sandwich.Severity,
74				Evidence: []string{
75					"front-run by " + front.Trader + " at gas " + strconv.FormatInt(front.GasPrice, 10),
76					"back-run by " + back.Trader + " at gas " + strconv.FormatInt(back.GasPrice, 10),
77					"victim gas " + strconv.FormatInt(target.GasPrice, 10),
78				},
79			}}
80		}
81		if gasDominates(front.GasPrice, target.GasPrice, int64(rules.Displacement.Multiplier)) {
82			return []Finding{{TxHash: victim, Kind: "displacement", Severity: rules.Displacement.Severity,
83				Evidence: []string{"front gas dominates victim by more than 2x"}}}
84		}
85		return nil
86	}
87	
88	// findSwap returns the record whose TxHash equals hash. TxHash is unique
89	// among the valid records replay accepts.
90	func findSwap(swaps []Swap, hash string) (Swap, bool) {
91		for _, s := range swaps {
92			if s.TxHash == hash {
93				return s, true
94			}
95		}
96		return Swap{}, false
97	}
98	
99	// Rank orders findings by severity then hash.
100	func Rank(findings []Finding) []Finding {
101		sorted := append([]Finding(nil), findings...)
102		sort.Slice(sorted, func(i, j int) bool {
103			if sorted[i].Severity == sorted[j].Severity {
104				return sorted[i].TxHash < sorted[j].TxHash
105			}
106			return sorted[i].Severity > sorted[j].Severity
107		})
108		return sorted
109	}
