1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"strings"
12		"syscall"
13	)
14	
15	// BuiltinVersionID identifies the built-in rule version, which reproduces
16	// the original fixed rules. It is always available, its parameters are
17	// queryable, and it cannot be overridden.
18	const BuiltinVersionID = "builtin"
19	
20	// ErrUnknownVersion reports a reference to a rule version that was never
21	// registered in the archive.
22	var ErrUnknownVersion = errors.New("unknown version")
23	
24	// ErrVersionConflict reports a re-registration of an existing version ID
25	// with different parameters.
26	var ErrVersionConflict = errors.New("version already registered with different parameters")
27	
28	// SandwichRule configures the sandwich rule: whether it runs and the
29	// severity of its conclusions.
30	type SandwichRule struct {
31		Enabled  bool `json:"enabled"`
32		Severity int  `json:"severity"`
33	}
34	
35	// DisplacementRule configures the displacement rule. A victim is flagged
36	// only when the previous swap's GasPrice strictly exceeds Multiplier times
37	// the victim's.
38	type DisplacementRule struct {
39		Enabled    bool `json:"enabled"`
40		Severity   int  `json:"severity"`
41		Multiplier int  `json:"multiplier"`
42	}
43	
44	// RuleSet is the complete declaration of both detection rules. Every
45	// version must declare both rules in full.
46	type RuleSet struct {
47		Sandwich     SandwichRule     `json:"sandwich"`
48		Displacement DisplacementRule `json:"displacement"`
49	}
50	
51	// RuleVersion is a named, immutable set of rule parameters.
52	type RuleVersion struct {
53		ID    string  `json:"id"`
54		Rules RuleSet `json:"rules"`
55	}
56	
57	// BuiltinVersion returns the version representing the original fixed
58	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
59	func BuiltinVersion() RuleVersion {
60		return RuleVersion{
61			ID: BuiltinVersionID,
62			Rules: RuleSet{
63				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
64				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
65			},
66		}
67	}
68	
69	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
70	// distinguish a missing field from an explicit zero value, and the decoder
71	// rejects unknown fields (including unknown rule names).
72	type toggleSpec struct {
73		Enabled  *bool `json:"enabled"`
74		Severity *int  `json:"severity"`
75	}
76	
77	type displacementSpec struct {
78		Enabled    *bool `json:"enabled"`
79		Severity   *int  `json:"severity"`
80		Multiplier *int  `json:"multiplier"`
81	}
82	
83	type versionSpec struct {
84		ID    *string `json:"id"`
85		Rules *struct {
86			Sandwich     *toggleSpec       `json:"sandwich"`
87			Displacement *displacementSpec `json:"displacement"`
88		} `json:"rules"`
89	}
90	
91	func parseEnabled(name string, v *bool) (bool, error) {
92		if v == nil {
93			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
94		}
95		return *v, nil
96	}
97	
98	func parseSeverity(name string, v *int) (int, error) {
99		if v == nil {
100			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
101		}
102		if *v < 1 || *v > 5 {
103			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
104		}
105		return *v, nil
106	}
107	
108	// ErrDuplicateField reports a JSON object in a registration spec that
109	// names the same field twice. Field names are compared the way JSON
110	// decoding matches struct fields, so two spellings that differ only in
111	// case (for example "severity" and "Severity") are also duplicates.
112	var ErrDuplicateField = errors.New("duplicate field in version spec")
113	
114	// ErrTrailingData reports non-whitespace content after the single JSON
115	// object that makes up a registration spec: a second object, another
116	// JSON value, an unmatched bracket or any other character.
117	var ErrTrailingData = errors.New("unexpected trailing data after version spec")
118	
119	// validateSpecStructure proves raw contains exactly one JSON object with
120	// no repeated fields anywhere in it, and nothing but whitespace around
121	// it. Keys are matched case-insensitively against the known fields of
122	// the version, rules, sandwich and displacement objects, preserving the
123	// decoder's case-compatible field matching: "SEVERITY" and "severity"
124	// point at the same field and cannot both appear. Escaped key spellings
125	// are decoded before comparison, so "severity" cannot evade it.
126	func validateSpecStructure(raw []byte) error {
127		dec := json.NewDecoder(bytes.NewReader(raw))
128		first, err := dec.Token()
129		if err != nil {
130			if errors.Is(err, io.EOF) {
131				return errors.New("version spec must be a JSON object, got empty input")
132			}
133			return fmt.Errorf("invalid version spec: %w", err)
134		}
135		if first != json.Delim('{') {
136			if first == nil {
137				return errors.New("version spec must be a JSON object, got null")
138			}
139			if d, ok := first.(json.Delim); ok && d == '[' {
140				return errors.New("version spec must be a single JSON object, got array")
141			}
142			return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(first))
143		}
144		if err := scanObject(dec, versionFields, "version spec"); err != nil {
145			return err
146		}
147		// Inspect the raw remainder instead of decoding another token: the
148		// only legal content after the object is JSON whitespace, and this
149		// names an unmatched '}' or ']' directly rather than as a syntax error.
150		rest := bytes.TrimLeft(raw[dec.InputOffset():], " \t\n\r")
151		if len(rest) > 0 {
152			return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
153		}
154		return nil
155	}
156	
157	func trailingTokenName(b byte) string {
158		switch b {
159		case '{':
160			return "object"
161		case '[':
162			return "array"
163		case '}':
164			return "extra closing brace '}'"
165		case ']':
166			return "extra closing bracket ']'"
167		case '"':
168			return "string"
169		case 't', 'f':
170			return "boolean"
171		case 'n':
172			return "null"
173		default:
174			if (b >= '0' && b <= '9') || b == '-' {
175				return "number"
176			}
177			return fmt.Sprintf("unexpected character %q", rune(b))
178		}
179	}
180	
181	// scanObject consumes one open object (its opening brace already read)
182	// and checks its keys against known. obj names the object for duplicate
183	// error messages. Nested "rules", "sandwich" and "displacement" objects
184	// are scanned with their own field tables; any other nested container is
185	// skipped without duplicate checking.
186	func scanObject(dec *json.Decoder, known map[string]string, obj string) error {
187		seen := make(map[string]string, len(known))
188		spellings := make(map[string]string)
189		for dec.More() {
190			keyTok, err := dec.Token()
191			if err != nil {
192				return fmt.Errorf("invalid version spec: %w", err)
193			}
194			key, ok := keyTok.(string)
195			if !ok {
196				return fmt.Errorf("invalid version spec: object key is %s, want string", jsonTokenName(keyTok))
197			}
198			// Exact repeat of a decoded key name (any field, known or unknown)
199			// is a duplicate; escapes are decoded first, so "id" == "id".
200			if first, dup := spellings[key]; dup {
201				return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, key, first)
202			}
203			spellings[key] = key
204			target, knownKey := known[strings.ToLower(key)]
205			if knownKey {
206				// A case-only spelling of the same known field is the same
207				// field: "Severity" and "severity" cannot share one object.
208				if first, dup := seen[target]; dup {
209					return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, target, first)
210				}
211				seen[target] = key
212			}
213			start, err := dec.Token()
214			if err != nil {
215				return fmt.Errorf("invalid version spec: %w", err)
216			}
217			if d, isDelim := start.(json.Delim); isDelim {
218				switch d {
219				case '{':
220					nested, hasShape := nestedObjectTables[target]
221					if !knownKey || !hasShape {
222						if err := skipValue(dec, '{'); err != nil {
223							return err
224						}
225						continue
226					}
227					if err := scanObject(dec, nested.fields, nested.label); err != nil {
228						return err
229					}
230				case '[':
231					if err := skipValue(dec, '['); err != nil {
232						return err
233					}
234				}
235				continue
236			}
237		}
238		closeTok, err := dec.Token()
239		if err != nil {
240			return fmt.Errorf("invalid version spec: %w", err)
241		}
242		if closeTok != json.Delim('}') {
243			return fmt.Errorf("invalid version spec: expected closing brace, got %s", jsonTokenName(closeTok))
244		}
245		return nil
246	}
247	
248	// skipValue consumes the remainder of one container whose opening
249	// delimiter has already been read, balancing nested brackets.
250	func skipValue(dec *json.Decoder, open json.Delim) error {
251		depth := 1
252		for depth > 0 {
253			tok, err := dec.Token()
254			if err != nil {
255				return fmt.Errorf("invalid version spec: %w", err)
256			}
257			if d, ok := tok.(json.Delim); ok {
258				switch d {
259				case '{', '[':
260					depth++
261				case '}', ']':
262					depth--
263					if depth == 0 && d != openBracketClose(open) {
264						return fmt.Errorf("invalid version spec: mismatched closing %s", jsonTokenName(d))
265					}
266				}
267			}
268		}
269		return nil
270	}
271	
272	func openBracketClose(open json.Delim) json.Delim {
273		if open == '[' {
274			return ']'
275		}
276		return '}'
277	}
278	
279	func jsonTokenName(tok json.Token) string {
280		switch t := tok.(type) {
281		case json.Delim:
282			switch t {
283			case '[':
284				return "array"
285			case '{':
286				return "object"
287			case ']':
288				return "extra closing bracket ']'"
289			case '}':
290				return "extra closing brace '}'"
291			}
292		case nil:
293			return "null"
294		case bool:
295			return "boolean"
296		case string:
297			return "string"
298		case json.Number:
299			return "number"
300		case float64:
301			return "number"
302		case int64:
303			return "number"
304		}
305		return "value"
306	}
307	
308	// fieldTable maps the case-insensitive spellings of a struct object's
309	// JSON fields to their canonical names.
310	func fieldTable(fields ...string) map[string]string {
311		table := make(map[string]string, len(fields))
312		for _, f := range fields {
313			table[strings.ToLower(f)] = f
314		}
315		return table
316	}
317	
318	type nestedObjectSpec struct {
319		fields map[string]string
320		label  string
321	}
322	
323	var (
324		versionFields      = fieldTable("id", "rules")
325		rulesFields        = fieldTable("sandwich", "displacement")
326		sandwichFields     = fieldTable("enabled", "severity")
327		displacementFields = fieldTable("enabled", "severity", "multiplier")
328		nestedObjectTables = map[string]nestedObjectSpec{
329			"rules":        {rulesFields, "rules object"},
330			"sandwich":     {sandwichFields, "rules.sandwich"},
331			"displacement": {displacementFields, "rules.displacement"},
332		}
333	)
334	
335	// ParseRuleVersion validates a registration document. It must contain
336	// exactly one complete JSON object (leading and trailing whitespace
337	// allowed): a second object or value, an unmatched bracket or any other
338	// trailing character fails, and empty input, arrays and null are not
339	// specs. Duplicate fields are rejected at the top level, in rules and in
340	// each rule's parameters, including case-only variants of the same known
341	// field. Missing fields, wrong types, out-of-range values and unknown
342	// rules or fields all fail with a reason.
343	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
344		if err := validateSpecStructure(raw); err != nil {
345			return RuleVersion{}, err
346		}
347		var spec versionSpec
348		dec := json.NewDecoder(bytes.NewReader(raw))
349		dec.DisallowUnknownFields()
350		if err := dec.Decode(&spec); err != nil {
351			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
352		}
353		if spec.ID == nil || *spec.ID == "" {
354			return RuleVersion{}, errors.New("id must be a non-empty string")
355		}
356		if spec.Rules == nil {
357			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
358		}
359		if spec.Rules.Sandwich == nil {
360			return RuleVersion{}, errors.New("rules.sandwich is required")
361		}
362		if spec.Rules.Displacement == nil {
363			return RuleVersion{}, errors.New("rules.displacement is required")
364		}
365		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
366		if err != nil {
367			return RuleVersion{}, err
368		}
369		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
370		if err != nil {
371			return RuleVersion{}, err
372		}
373		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
374		if err != nil {
375			return RuleVersion{}, err
376		}
377		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
378		if err != nil {
379			return RuleVersion{}, err
380		}
381		mult := spec.Rules.Displacement.Multiplier
382		if mult == nil {
383			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
384		}
385		if *mult < 2 || *mult > 100 {
386			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
387		}
388		return RuleVersion{
389			ID: *spec.ID,
390			Rules: RuleSet{
391				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
392				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
393			},
394		}, nil
395	}
396	
397	// findVersion resolves id against the built-in version and the archive's
398	// registered versions.
399	func findVersion(data archiveData, id string) (RuleVersion, error) {
400		if id == BuiltinVersionID {
401			return BuiltinVersion(), nil
402		}
403		for _, v := range data.Versions {
404			if v.ID == id {
405				return v, nil
406			}
407		}
408		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
409	}
410	
411	// enabledVersion resolves the archive's currently enabled version. Archives
412	// written before rule versions existed have no marker and run the built-in
413	// rules.
414	func (d archiveData) enabledVersion() (RuleVersion, error) {
415		if d.EnabledVersion == "" {
416			return BuiltinVersion(), nil
417		}
418		return findVersion(d, d.EnabledVersion)
419	}
420	
421	// RegisterVersion validates raw as a rule version spec and stores it in the
422	// archive at dir. Re-registering the same ID with identical parameters
423	// succeeds without adding a version (created is false); the same ID with
424	// different parameters is rejected. The built-in version ID is reserved.
425	// Any failure leaves the archive untouched.
426	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
427		v, err = ParseRuleVersion(raw)
428		if err != nil {
429			return RuleVersion{}, false, err
430		}
431		if v.ID == BuiltinVersionID {
432			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
433		}
434		if err := os.MkdirAll(dir, 0o755); err != nil {
435			return RuleVersion{}, false, err
436		}
437		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
438		if err != nil {
439			return RuleVersion{}, false, err
440		}
441		defer lock.Close()
442	
443		data, err := readArchive(dir)
444		if err != nil {
445			return RuleVersion{}, false, err
446		}
447		for _, existing := range data.Versions {
448			if existing.ID == v.ID {
449				if existing.Rules == v.Rules {
450					return existing, false, nil
451				}
452				return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
453			}
454		}
455		data.Versions = append(data.Versions, v)
456		if err := writeArchiveAtomic(dir, data); err != nil {
457			return RuleVersion{}, false, err
458		}
459		return v, true, nil
460	}
461	
462	// EnableVersion makes id the archive's active version for later replays.
463	// Enabling an unknown version fails and leaves the current enabled version
464	// unchanged.
465	func EnableVersion(dir, id string) (RuleVersion, error) {
466		if id == "" {
467			return RuleVersion{}, errors.New("version id must not be empty")
468		}
469		if err := os.MkdirAll(dir, 0o755); err != nil {
470			return RuleVersion{}, err
471		}
472		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
473		if err != nil {
474			return RuleVersion{}, err
475		}
476		defer lock.Close()
477	
478		data, err := readArchive(dir)
479		if err != nil {
480			return RuleVersion{}, err
481		}
482		v, err := findVersion(data, id)
483		if err != nil {
484			return RuleVersion{}, err
485		}
486		if data.EnabledVersion == id {
487			return v, nil
488		}
489		data.EnabledVersion = id
490		if err := writeArchiveAtomic(dir, data); err != nil {
491			return RuleVersion{}, err
492		}
493		return v, nil
494	}
495	
496	// ListVersions returns the built-in version plus every version registered
497	// in the archive, along with the currently enabled version ID.
498	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
499		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
500			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
501		}
502		lock, err := lockArchive(dir, syscall.LOCK_SH)
503		if err != nil {
504			return nil, "", err
505		}
506		defer lock.Close()
507	
508		data, err := readArchive(dir)
509		if err != nil {
510			return nil, "", err
511		}
512		versions = append([]RuleVersion{BuiltinVersion()}, data.Versions...)
513		enabled = data.EnabledVersion
514		if enabled == "" {
515			enabled = BuiltinVersionID
516		}
517		return versions, enabled, nil
518	}
519	
520	// GetVersion returns one version's full parameters by ID.
521	func GetVersion(dir, id string) (RuleVersion, error) {
522		if id == BuiltinVersionID {
523			return BuiltinVersion(), nil
524		}
525		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
526			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
527		}
528		lock, err := lockArchive(dir, syscall.LOCK_SH)
529		if err != nil {
530			return RuleVersion{}, err
531		}
532		defer lock.Close()
533	
534		data, err := readArchive(dir)
535		if err != nil {
536			return RuleVersion{}, err
537		}
538		return findVersion(data, id)
539	}
540	
541	// FindingChange pairs the archived and compared conclusions for one
542	// transaction whose kind or severity differs between the two versions.
543	type FindingChange struct {
544		TxHash   string        `json:"txHash"`
545		Original ReportFinding `json:"original"`
546		Compared ReportFinding `json:"compared"`
547	}
548	
549	// CompareResult is the outcome of re-judging one archived block under a
550	// different rule version. It carries both versions' parameters, both full
551	// conclusion sets, the raw swap evidence, and the per-transaction diff.
552	type CompareResult struct {
553		ChainID          string          `json:"chainId"`
554		BlockHash        string          `json:"blockHash"`
555		BlockNumber      int64           `json:"blockNumber"`
556		OriginalVersion  RuleVersion     `json:"originalVersion"`
557		ComparedVersion  RuleVersion     `json:"comparedVersion"`
558		OriginalFindings []ReportFinding `json:"originalFindings"`
559		ComparedFindings []ReportFinding `json:"comparedFindings"`
560		Swaps            []Swap          `json:"swaps"`
561		Added            []ReportFinding `json:"added"`
562		Removed          []ReportFinding `json:"removed"`
563		Changed          []FindingChange `json:"changed"`
564	}
565	
566	// Compare re-runs detection for one archived block under the given
567	// registered version and diffs the conclusions against the archived
568	// report. It only reads the archive: the original input file is not
569	// needed, and neither the archived report nor the enabled version is
570	// modified.
571	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
572		if _, err := os.Stat(dir); err != nil {
573			if errors.Is(err, os.ErrNotExist) {
574				return CompareResult{}, ErrUnknownBlock
575			}
576			return CompareResult{}, err
577		}
578		lock, err := lockArchive(dir, syscall.LOCK_SH)
579		if err != nil {
580			return CompareResult{}, err
581		}
582		defer lock.Close()
583	
584		data, err := readArchive(dir)
585		if err != nil {
586			return CompareResult{}, err
587		}
588		var rec *record
589		for i := range data.Records {
590			if data.Records[i].ChainID == chainID && data.Records[i].BlockHash == blockHash {
591				rec = &data.Records[i]
592				break
593			}
594		}
595		if rec == nil {
596			return CompareResult{}, ErrUnknownBlock
597		}
598		compared, err := findVersion(data, versionID)
599		if err != nil {
600			return CompareResult{}, err
601		}
602	
603		original := rec.Findings
604		if original == nil {
605			original = []ReportFinding{}
606		}
607		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
608		swaps := rec.Swaps
609		if swaps == nil {
610			swaps = []Swap{}
611		}
612	
613		origByTx := make(map[string]ReportFinding, len(original))
614		for _, f := range original {
615			origByTx[f.TxHash] = f
616		}
617		compByTx := make(map[string]ReportFinding, len(rejudged))
618		for _, f := range rejudged {
619			compByTx[f.TxHash] = f
620		}
621		added := []ReportFinding{}
622		removed := []ReportFinding{}
623		changed := []FindingChange{}
624		for _, f := range rejudged {
625			if o, ok := origByTx[f.TxHash]; ok {
626				// A transaction present on both sides with a different kind or
627				// severity is a change, never an add plus a remove.
628				if o.Kind != f.Kind || o.Severity != f.Severity {
629					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
630				}
631			} else {
632				added = append(added, f)
633			}
634		}
635		for _, f := range original {
636			if _, ok := compByTx[f.TxHash]; !ok {
637				removed = append(removed, f)
638			}
639		}
640		byTx := func(fs []ReportFinding) {
641			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
642		}
643		byTx(added)
644		byTx(removed)
645		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
646	
647		return CompareResult{
648			ChainID:          rec.ChainID,
649			BlockHash:        rec.BlockHash,
650			BlockNumber:      rec.BlockNumber,
651			OriginalVersion:  rec.ruleVersion(),
652			ComparedVersion:  compared,
653			OriginalFindings: original,
654			ComparedFindings: rejudged,
655			Swaps:            swaps,
656			Added:            added,
657			Removed:          removed,
658			Changed:          changed,
659		}, nil
660	}
661

